#!/usr/bin/env bun
/**
 * generate-plugin-manifest-schema.script.ts — the plugin manifest as a
 * published JSON Schema.
 *
 * The manifest was a zod schema reachable only by importing
 * `@delendai/core`, so a plugin written in another language had nothing
 * to validate its manifest against. The schema is generated from that
 * one zod source, regenerated by `gen:all`, and `--check` fails when the
 * committed file is stale.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { pluginManifestJsonSchema } from '@delendai/core/runtime';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');

/** Path of the committed schema, relative to the repo root. */
export const PLUGIN_MANIFEST_SCHEMA_PATH =
	'packages/core/schema/delendai.plugin-manifest.schema.json';

/** The JSON Schema text, exactly as written to disk. */
export const buildPluginManifestSchema = (): string => {
	const schema = {
		...pluginManifestJsonSchema(),
		$schema: 'http://json-schema.org/draft-07/schema#',
		$id: 'https://cartagogit.github.io/delendai/delendai.plugin-manifest.schema.json',
		title: 'delendai plugin manifest',
		description:
			'What a delendai plugin declares about itself (id, permissions, tools, presets, configuration docs), in any language.',
	};
	return `${JSON.stringify(schema, null, '\t')}\n`;
};

if (import.meta.main) {
	const out = join(ROOT, PLUGIN_MANIFEST_SCHEMA_PATH);
	const content = buildPluginManifestSchema();
	if (process.argv.includes('--check')) {
		let committed = '';
		try {
			committed = readFileSync(out, 'utf8');
		} catch {
			committed = '';
		}
		if (committed !== content) {
			console.error(
				'✖ plugin manifest schema is stale — run `bun run plugin-manifest:schema` and commit.',
			);
			process.exit(1);
		}
		console.log('plugin manifest schema up to date.');
	} else {
		mkdirSync(dirname(out), { recursive: true });
		writeFileSync(out, content);
		console.log(`wrote ${out}`);
	}
}
